ALTER TABLE products ADD COLUMN stock_location_id CHAR(36) NULL, ADD CONSTRAINT fk_product_stock_location FOREIGN KEY (tenant_id, establishment_id, stock_location_id) REFERENCES stock_locations (tenant_id, establishment_id, id);
ALTER TABLE product_variants ADD COLUMN stock_mode ENUM('SHARED','OWN') NOT NULL DEFAULT 'SHARED', ADD COLUMN stock_location_id CHAR(36) NULL, ADD UNIQUE KEY uq_variant_product (tenant_id, establishment_id, product_id, id), ADD CONSTRAINT fk_variant_stock_location FOREIGN KEY (tenant_id, establishment_id, stock_location_id) REFERENCES stock_locations (tenant_id, establishment_id, id);
ALTER TABLE stock_balances ADD COLUMN variant_id CHAR(36) NULL, ADD COLUMN variant_slot CHAR(36) GENERATED ALWAYS AS (COALESCE(variant_id,'00000000-0000-0000-0000-000000000000')) STORED, ADD UNIQUE KEY uq_stock_product_variant (tenant_id,establishment_id,location_id,product_id,variant_slot), DROP INDEX tenant_id, ADD CONSTRAINT fk_balance_variant_product FOREIGN KEY (tenant_id,establishment_id,product_id,variant_id) REFERENCES product_variants (tenant_id,establishment_id,product_id,id);
